<?php use App\Core\Csrf;$v=fn($k)=>$input[$k]??$user[$k]??'';$editing=(bool)$user;$currentUserId=(int)($user['id']??0); ?>
<div class="page-heading"><div><p class="eyebrow">Account administration</p><h1><?=$editing?'Edit user':'Create user'?></h1></div><a class="button" href="<?=e(url('/admin/users'))?>">Cancel</a></div><?php if($errors):?><div class="alert danger"><?=e($errors['form']??implode(' ',array_values($errors)))?></div><?php endif;?><form method="post" class="stack-form" action="<?=e($editing?url('/admin/users/'.$user['id']):url('/admin/users'))?>"><?=Csrf::field()?><section class="card form-section"><h2>Account</h2><div class="grid two"><label>Display name<input required name="display_name" value="<?=e($v('display_name'))?>"></label><label>Username<input required name="username" value="<?=e($v('username'))?>"></label><label>Email<input type="email" name="email" value="<?=e($v('email'))?>"></label><label>Status<select name="status"><?php foreach(['active','inactive','locked'] as $x):?><option value="<?=$x?>" <?=$v('status')===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label><label>Password<input type="password" name="password" minlength="10" <?=$editing?'':'required'?> autocomplete="new-password"><small><?=$editing?'Leave blank to retain the current password.':'At least 10 characters.'?></small></label></div></section><section class="card form-section"><h2>Roles</h2><div class="permission-grid"><?php foreach($roles as $role):?><label class="check-row"><input type="checkbox" name="roles[]" value="<?=$role['id']?>" <?=in_array((int)$role['id'],$selected,true)?'checked':''?>><span><strong><?=e($role['name'])?></strong><small><?=e($role['description'])?></small></span></label><?php endforeach;?></div></section><section class="card form-section"><h2>Profile access</h2><p><small>Link Student accounts to their own student profile and Teacher accounts to their teacher profile. A profile can belong to only one account.</small></p><div class="grid two"><label>Student profile<select name="student_profile_id"><option value="">Not linked</option><?php foreach($studentProfiles as $profile):?><?php $unavailable=$profile['user_id']!==null&&(int)$profile['user_id']!==$currentUserId;?><option value="<?=$profile['id']?>" <?=$v('student_profile_id')==(string)$profile['id']?'selected':''?> <?=$unavailable?'disabled':''?>><?=e($profile['student_no'].' — '.$profile['last_name'].', '.$profile['first_name'].($unavailable?' (linked to '.$profile['username'].')':''))?></option><?php endforeach;?></select></label><label>Teacher profile<select name="teacher_profile_id"><option value="">Not linked</option><?php foreach($teacherProfiles as $profile):?><?php $unavailable=$profile['user_id']!==null&&(int)$profile['user_id']!==$currentUserId;?><option value="<?=$profile['id']?>" <?=$v('teacher_profile_id')==(string)$profile['id']?'selected':''?> <?=$unavailable?'disabled':''?>><?=e($profile['employee_no'].' — '.$profile['last_name'].', '.$profile['first_name'].($unavailable?' (linked to '.$profile['username'].')':''))?></option><?php endforeach;?></select></label></div></section><div class="sticky-actions"><button class="button primary">Save account</button></div></form>
